finitions of the members of a nested class appear in the
namespace of the enclosing class:



    struct enclose
    {
        struct inner
        {
            static int x;
            void f(int i);
        };
    };
     
    int enclose::inner::x = 1;       // definition
    void enclose::inner::f(int i) {} // definition

Nested classes can be forward-declared and later defined, either within the
same enclosing class body, or outside of it:



    class enclose
    {
        class nested1;    // forward declaration
        class nested2;    // forward declaration
        class nested1 {}; // definition of nested class
    };
     
    class enclose::nested2 {}; // definition of nested class

Nested class declarations obey [ member access ](/w/cpp/language/access
"cpp/language/access") specifiers, a private member class cannot be named
outside the scope of the enclosing class, although objects of that class may
be manipulated:



    class enclose
    {
        struct nested // private member
        {
            void g() {}
        };
    public:
        static nested f() { return nested{}; }
    };
     
    int main()
    {
        //enclose::nested n1 = enclose::f(); // error: 'nested' is private
     
        enclose::f().g();       // OK: does not name 'nested'
        auto n2 = enclose::f(); // OK: does not name 'nested'
        n2.g();
    }

