If the ` Base ` base class subobject is not to be initialized as part of the `
Derived ` object (i.e., ` Base ` is a [ virtual base class
](/w/cpp/language/derived_class#Virtual_base_classes "cpp/language/derived
class") of ` Derived ` , and the ` Derived ` object is not the [ most derived
object ](/w/cpp/language/object#Subobjects "cpp/language/object") ), the
invocation of the inherited constructor, including the evaluation of any
arguments, is omitted:



    struct V
    {
        V() = default;
        V(int);
    };
     
    struct Q { Q(); };
     
    struct A : virtual V, Q
    {
        using V::V;
        A() = delete;
    };
     
    int bar() { return 42; }
     
    struct B : A
    {
        B() : A(bar()) {} // OK
    };
     
    struct C : B {};
     
    void foo()
    {
        C c; // “bar” is not invoked, because the V subobject
             // is not initialized as part of B
             // (the V subobject is initialized as part of C,
